use xiom.io;
interface Greetable {
  fn greet() -> Str;
}

type Person = {
  name: Str;
}

fn Person.greet(self) -> Str {
  return "Hi, I'm " + self.name;
}

type Robot = {
  model: Str;
}

fn Robot.greet(self) -> Str {
  return "Robot model: " + self.model;
}

type City = {
  city_name: Str;
}

fn City.greet(self) -> Str {
  return "Welcome to " + self.city_name;
}

fn announce[T: Greetable](thing: &T) {
  io.println(thing.greet());
}

fn main() -> Int {
  let p = Person{ name: "Alex" };
  let r = Robot{ model: "RX-9000" };
  let c = City{ city_name: "Paris" };
  announce(&p);
  announce(&r);
  announce(&c);
  return 0;
}
